
UPDATE public.faqs SET question = 'Apa saja yang bisa Fusionify kerjakan untuk bisnis kecil saya?', answer = 'Kami fokus pada solusi digital praktis: website UMKM & landing page (supaya pelanggan menemukan Anda di Google), automasi WhatsApp & chatbot (supaya admin tidak kewalahan), sistem sederhana untuk order/absen/data (supaya operasional lebih rapi), pengurusan domain & hosting, serta website resmi untuk sekolah, pesantren, dan komunitas.' WHERE id = '75fed131-2d08-4bb3-87e2-7f4ff4c0ff80';

UPDATE public.faqs SET question = 'Berapa lama pengerjaan sampai website atau sistem saya jadi?', answer = 'Landing page atau website UMKM biasanya 1–2 minggu. Automasi WhatsApp dasar 1–2 minggu. Website sekolah/komunitas dengan halaman lengkap 2–4 minggu. Sistem sederhana custom 3–6 minggu, tergantung fitur. Timeline pasti kami kunci di awal setelah kebutuhan disepakati.' WHERE id = 'a8b5b2f5-67d8-4bef-940b-25e653a54341';

UPDATE public.faqs SET question = 'Apakah ada garansi setelah website atau sistem diserahkan?', answer = 'Ya. Kami berikan garansi perbaikan bug gratis selama 30 hari setelah serah terima. Untuk update konten rutin, backup, dan pemantauan hosting, tersedia paket maintenance bulanan yang terjangkau — opsional, bukan wajib.' WHERE id = '70d5fdea-5df6-4c69-bf2b-87a9c0780d1d';

UPDATE public.faqs SET question = 'Bagaimana cara kerja sama dari awal sampai selesai?', answer = 'Alurnya sederhana: (1) konsultasi gratis via WhatsApp untuk mengerti masalah Anda, (2) kami kirim ringkasan scope, timeline, dan biaya, (3) setelah disepakati kami mulai kerjakan dengan update berkala, (4) Anda review dan minta revisi sesuai batas paket, (5) serah terima + panduan singkat cara pakai. Tidak ada jargon, tidak ada janji berlebihan.' WHERE id = '7d457440-e334-425c-96d6-ef854a8b07fb';

UPDATE public.faqs SET question = 'Apakah Fusionify cocok untuk perusahaan besar atau proyek enterprise?', answer = 'Jujur — tidak selalu. Kami tim kecil yang fokus membantu UMKM, sekolah, pesantren, komunitas, dan bisnis skala kecil–menengah. Untuk proyek yang butuh sertifikasi compliance berat (ISO, SOC2), tim delivery besar, atau SLA 24/7 enterprise, sebaiknya cari vendor yang memang setara kapasitasnya. Kami akan bilang terus terang kalau proyek Anda di luar kapasitas kami.' WHERE id = '0a4b0115-492e-4936-8cb5-33fc458a5c20';

UPDATE public.faqs SET question = 'Berapa biaya untuk membuat website atau automasi WhatsApp?', answer = 'Biaya tergantung kebutuhan spesifik — jumlah halaman, fitur, jumlah alur chat otomatis, dan integrasi. Karena setiap bisnis beda, kami tidak pasang harga tetap di website supaya tidak menyesatkan. Chat WhatsApp kami untuk konsultasi gratis, dan Anda akan dapat estimasi jelas sebelum memutuskan.' WHERE id = '96cb7d83-01b1-46c6-a4e5-84bbec479e87';

UPDATE public.faqs SET question = 'Apakah saya yang memiliki domain, hosting, dan akun setelah selesai?', answer = 'Ya, 100% milik Anda. Domain didaftarkan atas nama Anda, akses hosting dan seluruh akun (WhatsApp Business, media sosial, dashboard sistem) diserahkan lengkap. Kami tidak mengunci Anda — jika suatu hari pindah vendor lain, semua tetap bisa Anda bawa.' WHERE id = '57d867b8-e2f3-42b3-a023-edcdee37a4dc';

UPDATE public.faqs SET question = 'Apakah saya bisa minta revisi selama pengerjaan?', answer = 'Bisa. Jumlah revisi termasuk dalam paket akan kami tulis jelas di awal (misalnya 2–3 putaran revisi untuk landing page). Revisi kecil seperti ganti teks, warna, atau gambar biasanya cepat. Kalau ada perubahan scope besar di tengah jalan, kami diskusikan dulu dampaknya ke timeline dan biaya — supaya tidak ada kejutan.' WHERE id = 'b54ac2dc-263d-42ff-96dd-ecb739b19eec';
